Qed.
Lemma cred_pc : forall g1 i E1 cr1 ps1, CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps1 -> In (PML.ps_scap ps1) [66; 132; 264; 528; 1056] -> (CredV g1 i E1 cr1 <-> PML.pcredit_x L cr1 ps1 (kx + PMX.kenc L g1) (bxu + PMES.benc L g1)).
Proof.
  intros g1 i E1 cr1 ps1 Hd Hs. unfold CredV, bcap_of, scap_of. rewrite Hd. unfold PML.ps_blocks. cbn [nth snd].
  pose proof (KENC0 g1) as K1. pose proof (EK.benc_nonneg L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) g1) as B1.
  symmetry. exact (PPS.pcredit_x_bufcred L cr1 ps1 (kx + PMX.kenc L g1) (bxu + PMES.benc L g1) (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) Hs ltac:(lia) ltac:(lia)).
Qed.
