Lemma est_sv : forall E', env_agree GT.NF E0 E' -> estart E' (SA (EVar 2) SVOFF) = sp + SVOFF /\ estart E' (SA (EVar 2) (SVOFF + 8)) = sp + SVOFF + 8 /\ uv E' (APC.eaddz (EVar 2) SVOFF) = sp + SVOFF.
Proof.
  intros E' Hag.
  assert (VL : APC.expr_vars_lt GT.NF (EVar 2) = true) by (vm_compute; reflexivity).
  assert (VL2 : APC.expr_vars_lt GT.NF (APC.eaddz (EVar 2) SVOFF) = true) by (vm_compute; reflexivity).
  pose proof U2 as X2. pose proof SCRCV as SC.
  pose proof Hentry as (_ & _ & _ & _ & (T1 & T2 & T3 & T4 & _)).
  split; [|split].
  - rewrite (PB.estart_agree GT.NF E0 E' (EVar 2) SVOFF Hag VL). unfold estart. cbn [a_base a_off edenot]. rewrite X2. reflexivity.
  - rewrite (PB.estart_agree GT.NF E0 E' (EVar 2) (SVOFF + 8) Hag VL). unfold estart. cbn [a_base a_off edenot]. rewrite X2. lia.
  - rewrite (PB.uv_agree GT.NF E0 E' _ Hag VL2), PB.uv_eaddz. unfold PB.uv. cbn [edenot]. rewrite X2.
    apply Z.mod_small. unfold SVOFF. lia.
Qed.
